package blobatar

import (
	"bufio"
	"encoding/json"
	"math"
	"os"
	"testing"
)

// The synthetic examples were generated by Beans geometry.ts at the pinned
// fixture commit 4760281f2b9cb24eec4438a473e7226cd4e3980c using Bun 1.4.4.
func TestContourMatchesBeans(t *testing.T) {
	f, err := os.Open("testdata/contour/normalization.jsonl")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	count := 0
	for scanner.Scan() {
		var c struct {
			Path     string `json:"path"`
			Count    int    `json:"count"`
			Center   point  `json:"center"`
			Expected struct {
				Start    point        `json:"start"`
				Segments [][6]float64 `json:"segments"`
			} `json:"expected"`
		}
		if err := json.Unmarshal(scanner.Bytes(), &c); err != nil {
			t.Fatal(err)
		}
		curves, err := pathCubics(c.Path)
		if err != nil {
			t.Fatal(err)
		}
		got, err := normalizeContour(curves, c.Count, c.Center)
		if err != nil {
			t.Fatal(err)
		}
		if len(got.Segments) != len(c.Expected.Segments) {
			t.Fatalf("segments: %d != %d", len(got.Segments), len(c.Expected.Segments))
		}
		for i := range got.Start {
			if !(math.Abs(got.Start[i]-c.Expected.Start[i]) <= 1e-9) {
				t.Fatalf("start mismatch %v != %v", got.Start, c.Expected.Start)
			}
		}
		for i := range got.Segments {
			for j := range got.Segments[i] {
				if !(math.Abs(got.Segments[i][j]-c.Expected.Segments[i][j]) <= 1e-9) {
					t.Fatalf("path %q segment %d coordinate %d: %v != %v", c.Path, i, j, got.Segments[i][j], c.Expected.Segments[i][j])
				}
			}
		}
		count++
	}
	if err := scanner.Err(); err != nil {
		t.Fatal(err)
	}
	if count != 3 {
		t.Fatalf("expected 3 examples, got %d", count)
	}
}

func TestContourRejectsMalformedPaths(t *testing.T) {
	for _, s := range []string{"M 1", "M 0 0 X 1 2", "M 0 0 l 1 2", "M 0 0 C 1 2", "M 1e999 0"} {
		if _, err := pathCubics(s); err == nil {
			t.Errorf("accepted %q", s)
		}
	}
	if _, err := normalizeContour(nil, 2, point{}); err == nil {
		t.Error("accepted empty contour")
	}
	if _, err := normalizeContour([]bezier{{}, {}, {}}, 2, point{}); err == nil {
		t.Error("accepted too many segments")
	}
}
